#if UNITY_EDITOR || DEVELOPMENT_BUILD
using System;
using System.Collections;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using UnityEngine;
using UnityEngine.UI;
using TMPro;
using Yarn.Unity;
public sealed class CardinalArrivalCapture:MonoBehaviour
{
    string output;readonly List<string> checks=new List<string>();VariableSingleton.CampaignSave baseline;
    [RuntimeInitializeOnLoadMethod(RuntimeInitializeLoadType.BeforeSceneLoad)]static void Boot(){if(!Environment.GetCommandLineArgs().Contains("-cardinal-arrival-capture"))return;var p=Path.GetFullPath(Path.Combine(Application.dataPath,"../Captures/CardinalArrival"));Directory.CreateDirectory(p);SaveGames.TestRoot=Path.Combine(p,"Saves");Directory.CreateDirectory(SaveGames.TestRoot);VariableSingleton.TestSavePath=Path.Combine(SaveGames.TestRoot,"checkpoint.besieged.json");var go=new GameObject("Cardinal arrival verification");DontDestroyOnLoad(go);go.AddComponent<CardinalArrivalCapture>().output=p;}
    void Check(bool ok,string text){if(!ok)throw new Exception(text);checks.Add("PASS "+text);}
    void SetTurn(int turn){var data=JsonUtility.FromJson<VariableSingleton.CampaignSave>(JsonUtility.ToJson(baseline));data.turn=turn;VariableSingleton.Instance.RestoreValidated(data);ChurchCourt.Initialize();}
    void OnEnable(){Application.logMessageReceived+=Log;}
    void OnDisable(){Application.logMessageReceived-=Log;}
    void Log(string text,string stack,LogType type){if(type!=LogType.Exception)return;File.WriteAllText(Path.Combine(output,"failure.txt"),text+"\n"+stack);Application.Quit(1);}
    IEnumerator Start(){Application.runInBackground=true;AudioListener.volume=0;yield return null;SaveMenu.StartCampaign(false);float end=Time.realtimeSinceStartup+30;while(!VariableSingleton.IsInitialized&&Time.realtimeSinceStartup<end)yield return null;yield return new WaitForSecondsRealtime(.5f);Check(VariableSingleton.IsInitialized,"campaign initialized");baseline=VariableSingleton.Instance.CaptureState();
        foreach(int turn in new[]{0,8,9,10,11}){SetTurn(turn);Check(ChurchCourt.ArrivalDue==(turn==9),"arrival due only October "+turn);Check(!CourtRoster.InService(7)&&ChurchCourt.GennadiosAvailable,"initial service gates "+turn);Check(!ChurchCourt.Receive(-1)&&!ChurchCourt.Receive(3),"invalid options rejected "+turn);}
        Check(PreparationCampaign.FixedNode(11)=="story1"&&PreparationCampaign.Date(11)==new DateTime(1452,12,12),"December milestone preserved");
        for(int choice=0;choice<3;choice++){SetTurn(9);var before=VariableSingleton.Instance.CaptureState();string rng=JsonUtility.ToJson(UnityEngine.Random.state);int money=DailyLifeEvents.I("iMoney");Check(ChurchCourt.Receive(choice),"reception applies "+choice);Check(DailyLifeEvents.I("iLoyalty7")==new[]{55,45,50}[choice]&&DailyLifeEvents.I("iLoyalty203")==new[]{45,60,50}[choice],"exact loyalty pair "+choice);Check(!ChurchCourt.Receive(choice)&&!ChurchCourt.ArrivalDue,"cannot repeat "+choice);Check(money==DailyLifeEvents.I("iMoney")&&rng==JsonUtility.ToJson(UnityEngine.Random.state)&&VariableSingleton.Turn==9,"no economy time or RNG change "+choice);Check(PreparationCampaign.Flexible(9)&&PreparationCampaign.Unavailable(0,99)==null,"October preparation retained "+choice);Check(EventOutcome.Describe(before,VariableSingleton.Instance.CaptureState()).Contains("Reception Done")==false,"internal flag hidden "+choice);SaveGames.Checkpoint();var saved=SaveGames.Read(VariableSingleton.SavePath);SetTurn(0);VariableSingleton.Instance.RestoreValidated(saved.campaign);Check(!ChurchCourt.ArrivalDue&&CourtRoster.InService(7)&&DailyLifeEvents.I("iLoyalty203")==new[]{45,60,50}[choice],"save restore reception "+choice);}
        for(int union=0;union<3;union++){SetTurn(11);VariableSingleton.SetInt("iReligion",union);VariableSingleton.ChangeBool("bCharCardinal7",union!=0);PreparationCampaign.Complete("story1");Check(ChurchCourt.GennadiosAvailable==(union!=1),"Union Gennadios fate "+union);}
        SetTurn(11);VariableSingleton.SetInt("iReligion",0);VariableSingleton.ChangeBool("bCharCardinal7",true);PreparationCampaign.Complete("story1");Check(ChurchCourt.GennadiosAvailable&&CourtRoster.InService(7),"wartime compact keeps both");
        var manager=FindObjectOfType<ManagerUI>(true);var eventUI=FindObjectOfType<EventUI>(true);var council=CouncilUI.For(manager);
        foreach(int width in new[]{1280,1600}){Screen.SetResolution(width,width==1280?720:900,false);yield return new WaitForSecondsRealtime(.8f);for(int choice=0;choice<3;choice++){council.Hide();CampaignHUD.Instance.DismissReport();var running=eventUI.GetComponentInChildren<DialogueRunner>(true);if(running.IsDialogueRunning)running.Stop();eventUI.gameObject.SetActive(false);SetTurn(9);manager.gameObject.SetActive(false);eventUI.SetStartNode(ChurchCourt.ArrivalNode);eventUI.gameObject.SetActive(true);yield return new WaitForSecondsRealtime(.5f);var options=FindObjectsOfType<OptionButton>().Where(o=>o.IsInteractable()).ToArray();Check(options.Length==3,"three actual reception choices "+width+" "+choice);if(choice==0){yield return Capture("arrival-"+width);}options.First(o=>o.Option.Line.Text.Text.Contains(new[]{"Go personally", "Keep Isidore", "Leave his reception"}[choice])).InvokeOptionSelected();for(int i=0;running.IsDialogueRunning&&i<300;i++)yield return new WaitForSecondsRealtime(.03f);Check(!running.IsDialogueRunning&&CampaignHUD.Instance.HasModal,"Yarn outcome displayed "+width+" "+choice);Check(DailyLifeEvents.I("iLoyalty7")==new[]{55,45,50}[choice]&&DailyLifeEvents.I("iLoyalty203")==new[]{45,60,50}[choice],"actual option effects "+width+" "+choice);eventUI.ContinueToAssault();yield return null;Check(GameObject.Find("Monthly preparation")!=null&&VariableSingleton.Turn==9,"actual outcome returns to October choices "+width+" "+choice);var pass=GameObject.Find("Monthly preparation").GetComponentsInChildren<Button>().First(b=>b.GetComponentInChildren<TMP_Text>().text=="Pass this month");pass.onClick.Invoke();yield return new WaitForSecondsRealtime(.3f);var passOption=FindObjectsOfType<OptionButton>().First(o=>o.IsInteractable()&&o.Option.Line.Text.Text.Contains("Let the month pass"));passOption.InvokeOptionSelected();for(int i=0;running.IsDialogueRunning&&i<300;i++)yield return new WaitForSecondsRealtime(.03f);Check(!running.IsDialogueRunning,"pass preparation completes");eventUI.ContinueToAssault();yield return null;Check(VariableSingleton.Turn==10,"preparation advances exactly one month "+width+" "+choice);}
            CampaignHUD.Instance.DismissReport();council.Court();yield return null;Check(GameObject.Find("Council screen").GetComponentsInChildren<TMP_Text>().Any(t=>t.text.Contains("Gennadios Scholarios")),"Gennadios roster visible "+width);yield return Capture("court-"+width);typeof(CouncilUI).GetMethod("GardenTalk",System.Reflection.BindingFlags.Instance|System.Reflection.BindingFlags.NonPublic).Invoke(council,new object[]{ChurchCourt.Gennadios,0});yield return null;Check(GameObject.Find("Council screen").GetComponentsInChildren<TMP_Text>().Any(t=>t.text==ChurchCourt.Biography),"approved Gennadios introduction visible "+width);yield return Capture("gennadios-"+width);}
        File.WriteAllLines(Path.Combine(output,"details.txt"),checks);File.WriteAllText(Path.Combine(output,"checks.txt"),checks.Count+" checks passed");Application.Quit(0);
    }
    IEnumerator Capture(string name){yield return new WaitForSecondsRealtime(.12f);Canvas.ForceUpdateCanvases();var go=new GameObject("Capture camera",typeof(Camera));var camera=go.GetComponent<Camera>();camera.orthographic=true;camera.clearFlags=CameraClearFlags.SolidColor;camera.backgroundColor=Color.black;camera.nearClipPlane=.1f;camera.farClipPlane=100;var canvases=FindObjectsOfType<Canvas>().Where(c=>c.isRootCanvas).ToArray();var modes=canvases.Select(c=>c.renderMode).ToArray();var cams=canvases.Select(c=>c.worldCamera).ToArray();var distances=canvases.Select(c=>c.planeDistance).ToArray();var target=RenderTexture.GetTemporary(Screen.width,Screen.height,24);var prior=RenderTexture.active;Texture2D shot=null;try{camera.targetTexture=target;foreach(var c in canvases){c.renderMode=RenderMode.ScreenSpaceCamera;c.worldCamera=camera;c.planeDistance=10;}Canvas.ForceUpdateCanvases();camera.Render();RenderTexture.active=target;shot=new Texture2D(target.width,target.height,TextureFormat.RGB24,false);shot.ReadPixels(new Rect(0,0,target.width,target.height),0,0);shot.Apply();File.WriteAllBytes(Path.Combine(output,name+".png"),shot.EncodeToPNG());}finally{RenderTexture.active=prior;for(int i=0;i<canvases.Length;i++){canvases[i].renderMode=modes[i];canvases[i].worldCamera=cams[i];canvases[i].planeDistance=distances[i];}camera.targetTexture=null;RenderTexture.ReleaseTemporary(target);if(shot!=null)Destroy(shot);Destroy(go);}}
}
#endif
